class Solution {
    public int romanToInt(String s) {
        int[] vals = new int[256];
        vals['I'] = 1; vals['V'] = 5; vals['X'] = 10;
        vals['L'] = 50; vals['C'] = 100; vals['D'] = 500; vals['M'] = 1000;
        int total = 0, n = s.length();
        for (int i = 0; i < n; i++) {
            if (i + 1 < n && vals[s.charAt(i)] < vals[s.charAt(i + 1)]) {
                total -= vals[s.charAt(i)];
            } else {
                total += vals[s.charAt(i)];
            }
        }
        return total;
    }
}

var romanToInt = function(s) {
    const vals = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
    let total = 0;
    const n = s.length;
    for (let i = 0; i < n; i++) {
        if (i + 1 < n && vals[s[i]] < vals[s[i + 1]]) {
            total -= vals[s[i]];
        } else {
            total += vals[s[i]];
        }
    }
    return total;
};
